mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM company_post_like
    WHERE company_post_id = #{companyPostId}
        AND user_id = #{userId}
) AS isLiked;

mapper.delete:
DELETE from company_post_like
WHERE company_post_id = #{companyPostId}
    AND user_id = #{userId}

mapper.select:
SELECT company_post_like_count
FROM company_post
WHERE company_post_id = #{companyPostId}

mapper.update:
UPDATE company_post
SET company_post_like_count = company_post_like_count + 1
WHERE company_post_id = #{companyPostId}

UPDATE company_post
SET company_post_like_count = company_post_like_count - 1
WHERE company_post_id = #{companyPostId}
